    private static String mysqlIfToCase(String text) {
        int start=text.indexOf("IF(");if(start<0)return text;int depth=1,end=start+3,partStart=end;boolean quoted=false;var parts=new java.util.ArrayList<String>();
        for(;end<text.length();end++){char c=text.charAt(end);if(c=='\''){if(quoted && end+1<text.length() && text.charAt(end+1)=='\''){end++;continue;}quoted=!quoted;continue;}if(quoted)continue;if(c=='(')depth++;else if(c==')'){if(--depth==0){parts.add(text.substring(partStart,end));break;}}else if(c==',' && depth==1){parts.add(text.substring(partStart,end));partStart=end+1;}}
        if(parts.size()!=3 || depth!=0)throw new IllegalArgumentException("H2 IF adaptation");
        return mysqlIfToCase(text.substring(0,start)+"CASE WHEN "+mysqlIfToCase(parts.get(0))+" THEN "+mysqlIfToCase(parts.get(1))+" ELSE "+mysqlIfToCase(parts.get(2))+" END"+text.substring(end+1));
    }
    @SuppressWarnings("unchecked") private <T> ObjectProvider<T> provider(AtomicReference<T> value) {var port=mock(ObjectProvider.class);when(port.getIfAvailable()).thenAnswer(call->value.get());return port;}
    @BeforeEach void setup() throws Exception {
        data=new JdbcDataSource();data.setURL("jdbc:h2:mem:"+UUID.randomUUID()+";MODE=MySQL;DB_CLOSE_DELAY=-1;NON_KEYWORDS=ROLE;LOCK_TIMEOUT=5000");schema=data.getConnection();
        try(var sql=schema.createStatement()) {sql.execute("CREATE ALIAS UTC_TIMESTAMP FOR 'com.ruoyi.paiflow.service.ModelPersistenceTest.utcNow'");for(String file:List.of("sql/001-paiflow-schema.sql","sql/004-paiflow-membership.sql","sql/009-paiflow-model.sql","sql/010-paiflow-default-personal.sql")) {
            var ddl=Files.readString(Path.of(file),StandardCharsets.UTF_8).replaceAll("(?m)^--.*$","").replace(" STORED","").replace(" ENGINE=InnoDB DEFAULT CHARSET=utf8mb4","")
                .replace("IF(deleted = 0, name, NULL)","CASE WHEN deleted=0 THEN name ELSE NULL END")
                .replace("IF(team_id IS NULL, CONCAT('user:',owner_user_id), CONCAT('team:',team_id))","CASE WHEN team_id IS NULL THEN CONCAT('user:',owner_user_id) ELSE CONCAT('team:',team_id) END");
            // 隔离H2只转MySQL语法；保留生成列、唯一键和默认私域约束，未执行真实MySQL增量。
            ddl=ddl.replace("ALTER TABLE paiflow_space_member ADD COLUMN id BIGINT NOT NULL AUTO_INCREMENT,\n  ADD UNIQUE KEY uq_paiflow_space_member_id (id)","ALTER TABLE paiflow_space_member ADD COLUMN id BIGINT AUTO_INCREMENT UNIQUE")
                .replace("DROP CHECK ","DROP CONSTRAINT ").replace("ADD UNIQUE KEY uq_paiflow_default_owner (default_owner_user_id)","ADD CONSTRAINT uq_paiflow_default_owner UNIQUE (default_owner_user_id)");
            for(String statement:mysqlIfToCase(ddl).split(";"))if(!statement.isBlank())sql.execute(statement);
        }}
        var config=new Configuration(new Environment("model-isolated",new SpringManagedTransactionFactory(),data));
        for(String file:List.of("SpaceMapper","ModelMapper"))try(var xml=getClass().getResourceAsStream("/mapper/paiflow/"+file+".xml")){assertNotNull(xml);new XMLMapperBuilder(xml,config,file,config.getSqlFragments()).parse();}
        var template=new SqlSessionTemplate(new SqlSessionFactoryBuilder().build(config));mapper=template.getMapper(ModelMapper.class);spaces=template.getMapper(SpaceMapper.class);
        var identities=mock(IdentityMappingService.class);when(identities.current()).thenAnswer(call->{var user=new SysUser();user.setUserId(actor.get());user.setUserName("fixture-"+actor.get());return new LoginUser(actor.get(),8L,user,Set.of());});
        permissions=mock(PermissionService.class);when(permissions.hasPermi(anyString())).thenAnswer(call->!denied.contains(call.<String>getArgument(0)));
        var access=new ResourceAccessService(identities,permissions,spaces);access.useCurrentSession(template);var defaultProxy=new ProxyFactory(new DefaultPersonalSpaceService(spaces,identities,access));defaultProxy.setProxyTargetClass(true);defaultProxy.addAdvice(new TransactionInterceptor(new DataSourceTransactionManager(data),new AnnotationTransactionAttributeSource()));defaults=(DefaultPersonalSpaceService)defaultProxy.getProxy();
        var target=new ModelService(mapper,access,identities);var proxy=new ProxyFactory(target);proxy.setProxyTargetClass(true);proxy.addAdvice(new TransactionInterceptor(new DataSourceTransactionManager(data),new AnnotationTransactionAttributeSource()));service=(ModelService)proxy.getProxy();target.useDefaultSpaces(defaults);
        target.usePorts(provider(reference),provider(validator),provider(deployer),provider(new AtomicReference<>(service)));
        space=createSpace("模型fixture");other=createSpace("另一空间fixture");spaces.insertMember(space,43,3,"fixture");spaces.insertMember(other,43,3,"fixture");
    }
