    @Test void approvalThatExpiresWhileWaitingForSpaceLockCannotCommitEvenWhenReferenceVersionIsCurrent() throws Exception {
        ports();var granted=new AtomicReference<ModelService.Authorization>();reference.set(new ModelService.CredentialReferencePort(){public ModelService.Authorization authorize(ModelService.Candidate c){var a=ModelPersistenceTest.authorize(c);var shortGrant=new ModelService.Authorization(a.spaceId(),a.ownerUserId(),a.modelId(),a.candidateHash(),a.endpoint(),a.provider(),a.credentialRef(),a.credentialVersion(),a.authorizationId(),Instant.now().plusMillis(1500));granted.set(shortGrant);return shortGrant;}public boolean current(ModelService.Authorization a){return true;}});
        var locked=new CountDownLatch(1);var release=new CountDownLatch(1);var finalLockAttempt=new CountDownLatch(1);when(permissions.hasPermi("paiflow:model:create")).thenAnswer(call->{if(TransactionSynchronizationManager.isActualTransactionActive() && granted.get()!=null)finalLockAttempt.countDown();return true;});var pool=Executors.newFixedThreadPool(2);
        try{var holder=pool.submit(()->new TransactionTemplate(new DataSourceTransactionManager(data)).execute(status->{spaces.lock(space);locked.countDown();try{assertTrue(release.await(5,TimeUnit.SECONDS));}catch(InterruptedException error){throw new RuntimeException(error);}return null;}));assertTrue(locked.await(5,TimeUnit.SECONDS));var writer=pool.submit(()->{try{service.validateLegacy(space,null,original("过期批准不能保存"),false);return 200;}catch(ServiceException error){return error.getCode();}});assertTrue(finalLockAttempt.await(5,TimeUnit.SECONDS));assertNotNull(granted.get());long wait=Math.max(1,java.time.Duration.between(Instant.now(),granted.get().validUntil()).toMillis()+150);assertFalse(release.await(wait,TimeUnit.MILLISECONDS));assertTrue(granted.get().validUntil().isBefore(Instant.now()));release.countDown();holder.get(10,TimeUnit.SECONDS);int outcome=writer.get(10,TimeUnit.SECONDS);long rows=mapper.count(space,null,null);System.out.println("MODEL_APPROVAL_EXPIRY_PROBE expiredWhileLocked=true outcome="+outcome+" rows="+rows);assertEquals(409,outcome);assertEquals(0,rows);}finally{release.countDown();pool.shutdownNow();}
    }
    @Test void enableApprovalExpiryAfterLocalReferenceWaitMustLeaveActualModelDisabledAndVersionUntouched() throws Exception {
        ports();var wait=new java.util.concurrent.atomic.AtomicBoolean();var reached=new java.util.concurrent.atomic.AtomicBoolean();reference.set(new ModelService.CredentialReferencePort(){public ModelService.Authorization authorize(ModelService.Candidate c){var a=ModelPersistenceTest.authorize(c);return new ModelService.Authorization(a.spaceId(),a.ownerUserId(),a.modelId(),a.candidateHash(),a.endpoint(),a.provider(),a.credentialRef(),a.credentialVersion(),a.authorizationId(),Instant.now().plusSeconds(5));}public boolean current(ModelService.Authorization a){if(wait.get()){reached.set(true);assertTrue(a.validUntil().isAfter(Instant.now()));long remaining=Math.max(1,java.time.Duration.between(Instant.now(),a.validUntil()).toMillis()+100);try{assertFalse(new CountDownLatch(1).await(remaining,TimeUnit.MILLISECONDS));}catch(InterruptedException error){throw new RuntimeException(error);}assertTrue(a.validUntil().isBefore(Instant.now()));}return true;}});
        var created=service.validateLegacy(space,null,original("启用等待批准"),false);long id=created.getLongValue("id");service.switchEnabled(id,space,0L,false);wait.set(true);int outcome;try{service.switchEnabled(id,space,1L,true);outcome=200;}catch(ServiceException error){outcome=error.getCode();}System.out.println("MODEL_ENABLE_EXPIRY_PROBE currentWaitEntered="+reached.get()+" outcome="+outcome+" enabled="+mapper.find(id).getEnabled()+" revision="+mapper.find(id).getRevision());assertTrue(reached.get());assertEquals(409,outcome);assertEquals(0,mapper.find(id).getEnabled());assertEquals(1L,mapper.find(id).getRevision());assertEquals(2,mapper.countVersions(id));
    }
